(7013820, 1061342, 59737, '<td valign="top">Very nicely done, like that you left it in color, like the mix of sensuality and vulnerability that I get from this image</td>', 'Very nicely done, like that you left it in color, like the mix of sensuality and vulnerability that I get from this image', '2013-04-04 21:39:15.000000', NULL, 1),
(7013823, 1061223, 59737, '<td valign="top">Bold shot, has a quirkiness to it and there''s a lot going on with the tones, reflections and textures of the window frame</td>', 'Bold shot, has a quirkiness to it and there''s a lot going on with the tones, reflections and textures of the window frame', '2013-04-04 21:40:42.000000', NULL, 1),
(7013827, 1062207, 59737, '<td valign="top">Nice, love the softness of this, great B+W conversion</td>', 'Nice, love the softness of this, great B+W conversion', '2013-04-04 21:46:43.000000', NULL, 1),
(7013945, 1062034, 113016, '<td valign="top">Love the simplicity, the light and the retouching.  I do find her pose to be a bit awkward though.</td>', 'Love the simplicity, the light and the retouching.  I do find her pose to be a bit awkward though.', '2013-04-05 02:02:24.000000', NULL, 1),
(7013950, 1061387, 113016, '<td valign="top">One of my favorites because of the light,  and conversion.  Very nice.</td>', 'One of my favorites because of the light,  and conversion.  Very nice.', '2013-04-05 02:05:10.000000', NULL, 1),
(7013955, 1062060, 113016, '<td valign="top">Another favorite. I love the comp.   the dof and angle to the bldg across the way is wonderful.</td>', 'Another favorite. I love the comp.   the dof and angle to the bldg across the way is wonderful.', '2013-04-05 02:06:36.000000', NULL, 1),
(7013959, 1061355, 113016, '<td valign="top">Really nice light and processing.  A favorite.</td>', 'Really nice light and processing.  A favorite.', '2013-04-05 02:07:43.000000', NULL, 1),
(7014013, 1061223, 97225, '<td valign="top">Very dramatic. Top pick.</td>', 'Very dramatic. Top pick.', '2013-04-05 03:36:04.000000', NULL, 1),
(7014014, 1062108, 97225, '<td valign="top">Really nice. Their carefreeness and friendship are tangible.</td>', 'Really nice. Their carefreeness and friendship are tangible.', '2013-04-05 03:37:04.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7014016, 1061387, 97225, '<td valign="top">Cute baby. Nice pose.</td>', 'Cute baby. Nice pose.', '2013-04-05 03:37:27.000000', NULL, 1),
(7014017, 1062167, 97225, '<td valign="top">Lovely curves and beautiful light.</td>', 'Lovely curves and beautiful light.', '2013-04-05 03:37:57.000000', NULL, 1),
(7014018, 1061342, 97225, '<td valign="top">Beautifully composed.</td>', 'Beautifully composed.', '2013-04-05 03:38:44.000000', NULL, 1),
(7014055, 1062148, 113156, '<td valign="top">Primitive man, very nicely done.</td>', 'Primitive man, very nicely done.', '2013-04-05 07:20:38.000000', NULL, 1),
(7014256, 1061573, 59029, '<td valign="top">great butt, but that sapling directly in front of her is a little distacting.</td>', 'great butt, but that sapling directly in front of her is a little distacting.', '2013-04-05 13:57:01.000000', NULL, 1),
(7014266, 1062207, 94265, '<td valign="top">littlemav....? I like this, very feminine. I''ve felt some of the entries are a bit too soft but the slight softness here works. My only criticism would''ve been to remove the ring, the way the light hits it slightly makes it almost compete for attention with the nipple, which defeats the purpose a wee bit. Otherwise, this is really nice.</td>', 'littlemav....? I like this, very feminine. I''ve felt some of the entries are a bit too soft but the slight softness here works. My only criticism would''ve been to remove the ring, the way the light hits it slightly makes it almost compete for attention with the nipple, which defeats the purpose a wee bit. Otherwise, this is really nice.', '2013-04-05 14:13:40.000000', NULL, 1),
(7014268, 1061799, 94265, '<td valign="top">I''m not keen on the unusual reversal of a light vignette on the edges and the centre of the photo being darker, I feel it would''ve worked better the other way around. I like the camera placement, lol.</td>', 'I''m not keen on the unusual reversal of a light vignette on the edges and the centre of the photo being darker, I feel it would''ve worked better the other way around. I like the camera placement, lol.', '2013-04-05 14:15:06.000000', NULL, 1),
(7014269, 1062124, 94265, '<td valign="top">I like the attempt at the close-in detail, although I feel it''s not as sharp as I''d like, there''s no skin or nipple detail where there should''ve been.</td>', 'I like the attempt at the close-in detail, although I feel it''s not as sharp as I''d like, there''s no skin or nipple detail where there should''ve been.', '2013-04-05 14:16:24.000000', NULL, 1),
(7014270, 1061355, 94265, '<td valign="top">There''s a background speck and one on his right shoulder that bug me a little but otherwise, lovely portrait. Great lighting, it really defines him.</td>', 'There''s a background speck and one on his right shoulder that bug me a little but otherwise, lovely portrait. Great lighting, it really defines him.', '2013-04-05 14:17:41.000000', NULL, 1),
(7014271, 1062054, 94265, '<td valign="top">Contrast is a bit too dark; this is downright creepy, haha!</td>', 'Contrast is a bit too dark; this is downright creepy, haha!', '2013-04-05 14:18:14.000000', NULL, 1),
(7014272, 1062107, 94265, '<td valign="top">The subject kinda works I guess, beautiful animal, although the white vignette is a bit intense; also, I''m a fan of colour popping but I think highlighting the golden brown eyes would''ve been enough. The little pop of pink on the teat looks a bit silly to me and seems un-necessary.</td>', 'The subject kinda works I guess, beautiful animal, although the white vignette is a bit intense; also, I''m a fan of colour popping but I think highlighting the golden brown eyes would''ve been enough. The little pop of pink on the teat looks a bit silly to me and seems un-necessary.', '2013-04-05 14:19:56.000000', NULL, 1),
(7014273, 1061800, 94265, '<td valign="top">It''s in focus and the blue background is nice but this doesn''t really stand out as anything special. The light is well-exposed but too even to be defining, the crop is a bit too simple also, bordering on bland.</td>', 'It''s in focus and the blue background is nice but this doesn''t really stand out as anything special. The light is well-exposed but too even to be defining, the crop is a bit too simple also, bordering on bland.', '2013-04-05 14:22:08.000000', NULL, 1),
(7014274, 1061223, 94265, '<td valign="top">Very dramatic! The leg posing is a bit too exaggerated to me but I like the overall effect, pretty cool.</td>', 'Very dramatic! The leg posing is a bit too exaggerated to me but I like the overall effect, pretty cool.', '2013-04-05 14:22:49.000000', NULL, 1),
(7014276, 1062059, 94265, '<td valign="top">This made me laugh. Technically very good, great light, nice and sharp, cute doggy. I''d have moved that water dish out of the shot but this is really good, if a little unusual for the challenge, haha. The title is fab too.</td>', 'This made me laugh. Technically very good, great light, nice and sharp, cute doggy. I''d have moved that water dish out of the shot but this is really good, if a little unusual for the challenge, haha. The title is fab too.', '2013-04-05 14:24:36.000000', NULL, 1),
(7014279, 1060786, 94265, '<td valign="top">Often with shots like these, I come away and look at the thumbnail as sometimes the subject somehow becomes clearer and I can judge it better, not with this though; I can''t make out anything going on here, not subject, intent, or perspective. Low scorer for me I''m afraid.</td>', 'Often with shots like these, I come away and look at the thumbnail as sometimes the subject somehow becomes clearer and I can judge it better, not with this though; I can''t make out anything going on here, not subject, intent, or perspective. Low scorer for me I''m afraid.', '2013-04-05 14:28:54.000000', NULL, 1),
(7014284, 1062100, 94265, '<td valign="top">Extremely noisy, I do get the connection with the title but nothing jumps out here for me I''m afraid.</td>', 'Extremely noisy, I do get the connection with the title but nothing jumps out here for me I''m afraid.', '2013-04-05 14:30:21.000000', NULL, 1),
(7014286, 1061387, 94265, '<td valign="top">I figured someone would do this, in fact I was expecting more shots of this nature, I''m surprised this is the only one, lol. I like the shot; lovely wee fellow, nice lighting, fits the challenge. Good job.</td>', 'I figured someone would do this, in fact I was expecting more shots of this nature, I''m surprised this is the only one, lol. I like the shot; lovely wee fellow, nice lighting, fits the challenge. Good job.', '2013-04-05 14:31:56.000000', NULL, 1),
(7014287, 1061342, 94265, '<td valign="top">Good lines and shapes made here. I don''t mind the small portion of her face being visible, although I''d love to see what this would be like if she''d lifted her head up out of the way and we just saw those shoulder and knee curves with the lines and light. Nice work overall.</td>', 'Good lines and shapes made here. I don''t mind the small portion of her face being visible, although I''d love to see what this would be like if she''d lifted her head up out of the way and we just saw those shoulder and knee curves with the lines and light. Nice work overall.', '2013-04-05 14:33:15.000000', NULL, 1),
(7014289, 1061573, 94265, '<td valign="top">A more shallow DOF would''ve helped this I think, there''s an awful lot of messy distractions going on with all those twigs and things. I also wouldn''t have cropped it quite so close to her head. She has a great figure, the exposure is good and the focus is clear, overall though this isn''t a stand out entry for me. I don''t know if the skinny tree trunk we can see between her legs was a deliberate angling to include it in that place or not, if it was then I feel it should be funny but it''s just a bit crass; if it was accidental, watch out for such things next time!</td>', 'A more shallow DOF would''ve helped this I think, there''s an awful lot of messy distractions going on with all those twigs and things. I also wouldn''t have cropped it quite so close to her head. She has a great figure, the exposure is good and the focus is clear, overall though this isn''t a stand out entry for me. I don''t know if the skinny tree trunk we can see between her legs was a deliberate angling to include it in that place or not, if it was then I feel it should be funny but it''s just a bit crass; if it was accidental, watch out for such things next time!', '2013-04-05 14:38:14.000000', NULL, 1),
(7014292, 1062101, 94265, '<td valign="top">I like the props here but with the reflections, there is an awful lot going on, I find my eyes wandering too much and not settling on anything in particular. Nice subdued warm tones though.</td>', 'I like the props here but with the reflections, there is an awful lot going on, I find my eyes wandering too much and not settling on anything in particular. Nice subdued warm tones though.', '2013-04-05 14:40:01.000000', NULL, 1),
(7014298, 1062020, 94265, '<td valign="top">This could be viewed as a comment on social acceptance norms and the perception of beauty, i.e. the man is walking away from the statue of the very rotund lady, which reflects a lot of the feeling amongst men concerning real women in everyday life, due in part to the standards of beauty put upon us by media. I''m actually bumping my vote up on this one since it made me ponder.</td>', 'This could be viewed as a comment on social acceptance norms and the perception of beauty, i.e. the man is walking away from the statue of the very rotund lady, which reflects a lot of the feeling amongst men concerning real women in everyday life, due in part to the standards of beauty put upon us by media. I''m actually bumping my vote up on this one since it made me ponder.', '2013-04-05 14:42:52.000000', NULL, 1),
(7014303, 1062145, 94265, '<td valign="top">I Googled ailurophobia, perfect title choice, haha. That cat looks positively shocked! I like the model, she''s very relaxed in her expression and modest pose. Her right foot is very blown out and the white chair being there seems kinda random when there''s a couch right behind her; I feel that having her sitting a bit further back on the actual couch would''ve made more sense. The cropped off bottom of her shoe draws my eye but I''m really pernickity about things like that, lol. Still, I like the shot overall, good work.</td>', 'I Googled ailurophobia, perfect title choice, haha. That cat looks positively shocked! I like the model, she''s very relaxed in her expression and modest pose. Her right foot is very blown out and the white chair being there seems kinda random when there''s a couch right behind her; I feel that having her sitting a bit further back on the actual couch would''ve made more sense. The cropped off bottom of her shoe draws my eye but I''m really pernickity about things like that, lol. Still, I like the shot overall, good work.', '2013-04-05 14:48:44.000000', NULL, 1),
(7014304, 1062057, 94265, '<td valign="top">As a matter of personal taste, I don''t like smoking shots but I like the model''s tattoo, draws the eye right up her back to her neck, it works well. Her hair looks a bit soft; since so much of it is lost in the shadow, I might have had her pull it forward so a little more of her back was exposed.</td>', 'As a matter of personal taste, I don''t like smoking shots but I like the model''s tattoo, draws the eye right up her back to her neck, it works well. Her hair looks a bit soft; since so much of it is lost in the shadow, I might have had her pull it forward so a little more of her back was exposed.', '2013-04-05 14:51:01.000000', NULL, 1),
(7014306, 1062148, 94265, '<td valign="top">Interesting, quite beautiful, makes me think of something from a dream you can''t fully remember when you''ve just woken up. I like the light on the model, it defines the muscle well. You''ve still managed to get a good focus on the torso depsite the ghostly effect of the long exposure. Nice warm tones too, great job.</td>', 'Interesting, quite beautiful, makes me think of something from a dream you can''t fully remember when you''ve just woken up. I like the light on the model, it defines the muscle well. You''ve still managed to get a good focus on the torso depsite the ghostly effect of the long exposure. Nice warm tones too, great job.', '2013-04-05 14:53:18.000000', NULL, 1),
(7014312, 1061768, 94265, '<td valign="top">Nice lighting on her legs and arms, nothing distracting out of the window either, I like the material drape too as it''s more interesting than a dark shadow there. Part of me likes the motion blur of her head as it enhances the idea of anonymity, although part of me wishes she''d been still so we could see the details of her hair too.</td>', 'Nice lighting on her legs and arms, nothing distracting out of the window either, I like the material drape too as it''s more interesting than a dark shadow there. Part of me likes the motion blur of her head as it enhances the idea of anonymity, although part of me wishes she''d been still so we could see the details of her hair too.', '2013-04-05 14:56:13.000000', NULL, 1),
(7014318, 1062130, 94265, '<td valign="top">Doesn''t quite fit the challenge but it''s amusing and made me smile.</td>', 'Doesn''t quite fit the challenge but it''s amusing and made me smile.', '2013-04-05 14:59:49.000000', NULL, 1),
(7014323, 1062060, 94265, '<td valign="top">The title alone invokes a whole story to me; the morning after a party weekend, they''ve woken up with someone they didn''t expect and maybe hadn''t admitted they wanted, yet not in a comical way. Their stares out of the window and the linked arms make it poignant, like they''ve hit this huge realisation and their whole future is out there now.</td>', 'The title alone invokes a whole story to me; the morning after a party weekend, they''ve woken up with someone they didn''t expect and maybe hadn''t admitted they wanted, yet not in a comical way. Their stares out of the window and the linked arms make it poignant, like they''ve hit this huge realisation and their whole future is out there now.', '2013-04-05 15:15:10.000000', NULL, 1),
(7014326, 1062111, 94265, '<td valign="top">Love the idea. It''s a shame the voyeur is tucked away, I''d have liked to have seen a bit more of him and his pose, to try to work out how he is feeling. I know the usual idea of a voyeur is being hidden, so it does work here; I just think because the subject of his voyeurism is so still and incapable of awareness of him, it''d have been an interesting change to see him more clearly. Overall though, I do like the shot.</td>', 'Love the idea. It''s a shame the voyeur is tucked away, I''d have liked to have seen a bit more of him and his pose, to try to work out how he is feeling. I know the usual idea of a voyeur is being hidden, so it does work here; I just think because the subject of his voyeurism is so still and incapable of awareness of him, it''d have been an interesting change to see him more clearly. Overall though, I do like the shot.', '2013-04-05 15:23:40.000000', NULL, 1),
(7014328, 1062034, 94265, '<td valign="top">This simple set-up works well, very pretty image; it''s classic attractive glamour, without the popular (yet not as good in my opinion) sleazy edge.</td>', 'This simple set-up works well, very pretty image; it''s classic attractive glamour, without the popular (yet not as good in my opinion) sleazy edge.', '2013-04-05 15:26:18.000000', NULL, 1),
(7014332, 1061240, 94265, '<td valign="top">Very interesting pose, I like how her closed eyes are just visible through the material. There are some blown out spots but they kinda work. My main niggle is the black fingernails on only one hand, I can''t work out why you chose that.</td>', 'Very interesting pose, I like how her closed eyes are just visible through the material. There are some blown out spots but they kinda work. My main niggle is the black fingernails on only one hand, I can''t work out why you chose that.', '2013-04-05 15:27:57.000000', NULL, 1),
(7014336, 1062024, 94265, '<td valign="top">I might have preferred this without the lower half of the face visible, as all the interesting shadows and details are on the body and the jeans. I like the simplicity here and the pose. Going ''commando'' eh, lol.</td>', 'I might have preferred this without the lower half of the face visible, as all the interesting shadows and details are on the body and the jeans. I like the simplicity here and the pose. Going ''commando'' eh, lol.', '2013-04-05 15:30:17.000000', NULL, 1),
(7014339, 1061368, 94265, '<td valign="top">Her pose is very sad. The props there make me think of a lonely cleaner/janitor who has died and is still tied to the toil of her unhappy life. Or, it could possibly represent the anguished feelings of a woman who suffers at the hands of a man in that little room. Lots of ideas come to mind! Good job with the ghostly effect, I like this overall.</td>', 'Her pose is very sad. The props there make me think of a lonely cleaner/janitor who has died and is still tied to the toil of her unhappy life. Or, it could possibly represent the anguished feelings of a woman who suffers at the hands of a man in that little room. Lots of ideas come to mind! Good job with the ghostly effect, I like this overall.', '2013-04-05 15:32:07.000000', NULL, 1),
(7014343, 1062108, 94265, '<td valign="top">Technically a pretty good shot, nice clear details in the DOF from the long grass to the boys. It took me a while to make a connection with the title and find the idea you might have been going for but it puts me in mind of the two playing boys deciding to skinny dip on a warm day, then walking home holding their clothes while the sun dries them, joking and laughing. I find my eyes drawn to the reflective face of the boy''s watch, I might''ve got him to ditch it before taking the shot.</td>', 'Technically a pretty good shot, nice clear details in the DOF from the long grass to the boys. It took me a while to make a connection with the title and find the idea you might have been going for but it puts me in mind of the two playing boys deciding to skinny dip on a warm day, then walking home holding their clothes while the sun dries them, joking and laughing. I find my eyes drawn to the reflective face of the boy''s watch, I might''ve got him to ditch it before taking the shot.', '2013-04-05 15:38:19.000000', NULL, 1),
(7014349, 1062167, 94265, '<td valign="top">Part of me thinks this is quite pretty but another part of me longs for something more to focus on. The only point of focus seems to be that one line at the edge of her shin/calf, which also looks a wee bit blown out to me. As much as the image is feminine and fits the challenge, I don''t think there''s quite enough here to keep me looking.</td>', 'Part of me thinks this is quite pretty but another part of me longs for something more to focus on. The only point of focus seems to be that one line at the edge of her shin/calf, which also looks a wee bit blown out to me. As much as the image is feminine and fits the challenge, I don''t think there''s quite enough here to keep me looking.', '2013-04-05 15:46:40.000000', NULL, 1),
(7014352, 1062202, 94265, '<td valign="top">This could''ve been a nice, bold image but to be honest, the processing totally spoils it for me. There are strange patches of blurred area and other areas that are over-sharp, it messes with the perspective, like you had quite a wide area of focus and have tried to create a sense of a shallower DOF. Her mouth almost looks painted on because of the lack of detail there; the oversharpening on the nipples is the worst part, they look unnatural and it doesn''t make sense with how much of the rest of the breasts are blurred.</td>', 'This could''ve been a nice, bold image but to be honest, the processing totally spoils it for me. There are strange patches of blurred area and other areas that are over-sharp, it messes with the perspective, like you had quite a wide area of focus and have tried to create a sense of a shallower DOF. Her mouth almost looks painted on because of the lack of detail there; the oversharpening on the nipples is the worst part, they look unnatural and it doesn''t make sense with how much of the rest of the breasts are blurred.', '2013-04-05 15:51:27.000000', NULL, 1),
(7014363, 1062065, 94265, '<td valign="top">Puts me in mind of those naked house cleaners who charge a fortune to clean your house in the nude, lol. Amusing but could do with a bit more work; that dark shadow around him suggests you''ve used too harsh a light (on camera flash?), plus the crop is very tight. Next time, try a more diffused light or even experiment with more creative lighting. Don''t be afraid to try out different crops and angles too.</td>', 'Puts me in mind of those naked house cleaners who charge a fortune to clean your house in the nude, lol. Amusing but could do with a bit more work; that dark shadow around him suggests you''ve used too harsh a light (on camera flash?), plus the crop is very tight. Next time, try a more diffused light or even experiment with more creative lighting. Don''t be afraid to try out different crops and angles too.', '2013-04-05 16:02:36.000000', NULL, 1),
(7014366, 1062139, 94265, '<td valign="top">Good idea, nice pose, good use of filling the frame; the saturation looks a bit too strong on the blues and cyans, there''s an odd patch of blur under the right arm too that''s a bit distracting. Did you do a bit of warping or liquify? Some of the edges near the blur look a wee bit untidy.</td>', 'Good idea, nice pose, good use of filling the frame; the saturation looks a bit too strong on the blues and cyans, there''s an odd patch of blur under the right arm too that''s a bit distracting. Did you do a bit of warping or liquify? Some of the edges near the blur look a wee bit untidy.', '2013-04-05 16:05:29.000000', NULL, 1),
(7014370, 1062206, 94265, '<td valign="top">I agree with the title, although this shot doesn''t majorly pop for me. The tones overall are a bit too warm and the light isn''t interesting. The main distraction is the big blown-out spot on the right side of the shot, it looks like there''s tinsel or some kind of metal that''s catching the light (possibly the texture of the window glass?) which very much takes my eye away from the feet. Nice nail polish though!</td>', 'I agree with the title, although this shot doesn''t majorly pop for me. The tones overall are a bit too warm and the light isn''t interesting. The main distraction is the big blown-out spot on the right side of the shot, it looks like there''s tinsel or some kind of metal that''s catching the light (possibly the texture of the window glass?) which very much takes my eye away from the feet. Nice nail polish though!', '2013-04-05 16:08:17.000000', NULL, 1),
(7014375, 1062156, 94265, '<td valign="top">I like the pose and the filling of the frame, even if it is quite noisy. I like the black band of light over the eyes, it works really well on a nude, although I''m not as keen on it over the ankle and thigh; I think more natural shadows there to hide his modesty rather than such a block black cloaking would''ve been a bit better.</td>', 'I like the pose and the filling of the frame, even if it is quite noisy. I like the black band of light over the eyes, it works really well on a nude, although I''m not as keen on it over the ankle and thigh; I think more natural shadows there to hide his modesty rather than such a block black cloaking would''ve been a bit better.', '2013-04-05 16:10:04.000000', NULL, 1),
(7014376, 1062037, 94265, '<td valign="top">I don''t dislike these type of shots as much as I used to. This one is quite cool, very little detail on the human form but just enough to perpetuate the nude idea. I don''t entirely understand the title though and the setting looks a bit odd for this type of shot.</td>', 'I don''t dislike these type of shots as much as I used to. This one is quite cool, very little detail on the human form but just enough to perpetuate the nude idea. I don''t entirely understand the title though and the setting looks a bit odd for this type of shot.', '2013-04-05 16:11:56.000000', NULL, 1),
(7014377, 1062171, 94265, '<td valign="top">I get what you''re going for obviously but it doesn''t really resonate with me. Maybe if there were wires exposed and more of the innards of the machine on display but as it is, it doesn''t really say ''exposed'' to me. I''m also not too keen on the almost half sepia, half b&amp;w look.</td>', 'I get what you''re going for obviously but it doesn''t really resonate with me. Maybe if there were wires exposed and more of the innards of the machine on display but as it is, it doesn''t really say ''exposed'' to me. I''m also not too keen on the almost half sepia, half b&w look.', '2013-04-05 16:14:02.000000', NULL, 1),
(7014384, 1062060, 62357, '<td valign="top">I can''t explain why I like this so much, but it is my top pick in this challenge.</td>', 'I can''t explain why I like this so much, but it is my top pick in this challenge.', '2013-04-05 16:29:17.000000', NULL, 1),
(7014471, 1062139, 114225, '<td valign="top">Very good use of light.</td>', 'Very good use of light.', '2013-04-05 20:39:27.000000', NULL, 1),
(7014473, 1062108, 114225, '<td valign="top">Freedom. Nice.</td>', 'Freedom. Nice.', '2013-04-05 20:39:39.000000', NULL, 1),
(7014475, 1062207, 114225, '<td valign="top">Elegantly hidden. Well done.</td>', 'Elegantly hidden. Well done.', '2013-04-05 20:39:53.000000', NULL, 1),
(7014477, 1062167, 114225, '<td valign="top">Great suggestiveness.</td>', 'Great suggestiveness.', '2013-04-05 20:40:10.000000', NULL, 1),
(7014478, 1062145, 114225, '<td valign="top">The addition of the cat is a great touch.</td>', 'The addition of the cat is a great touch.', '2013-04-05 20:40:31.000000', NULL, 1),
