(7015188, 1062101, 100393, '<td valign="top">An interesting still life composition. I can see the care you have taken but there are others who have embraced the challenge to a greater degree..<br/> <br/>I do like the colours though.</td>', 'An interesting still life composition. I can see the care you have taken but there are others who have embraced the challenge to a greater degree.. I do like the colours though.', '2013-04-07 09:20:37.000000', NULL, 1),
(7015193, 1062065, 100393, '<td valign="top">Bold, bold, bold!<br/> <br/>I''d have really liked this if you''d have chosen your background to be a little more pleasing.</td>', 'Bold, bold, bold! I''d have really liked this if you''d have chosen your background to be a little more pleasing.', '2013-04-07 09:23:52.000000', NULL, 1),
(7015196, 1061387, 100393, '<td valign="top">This is a well executed baby picture but it doesn''t have the drama of many of the entries.</td>', 'This is a well executed baby picture but it doesn''t have the drama of many of the entries.', '2013-04-07 09:24:46.000000', NULL, 1),
(7015197, 1062171, 100393, '<td valign="top">I''m sure you''re getting hammered for this interpretation. I''m also sure you don''t mind too much! ;-)</td>', 'I''m sure you''re getting hammered for this interpretation. I''m also sure you don''t mind too much! ;-)', '2013-04-07 09:25:46.000000', NULL, 1),
